import clsx from 'clsx';
import React, { forwardRef } from 'react';
import { useIntl } from 'react-intl';

import { _useSharedProgressBarPropsContext } from './hooks/useProgressBarPropsContext.js';
import { progressBarValueCSS } from './ProgressBarValue.sty.js';
import { _isStringChildren } from '../../../core/utils/is-string-children.js';
import { textStyleCSS } from '../../../styles/textStyle.sty.js';
import type { DataTestId } from '../../types/data-props.js';
import type { StylingProps } from '../../types/styling-props.js';
import type { WithChildren } from '../../types/with-children.js';

/** Accepted properties for ProgressBarValue */
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface ProgressBarValueProps
  extends WithChildren,
    StylingProps,
    DataTestId {}

/** ProgressBarValue sub-component is rendered inside ProgressBar component. */
export const ProgressBarValue = forwardRef<
  HTMLDivElement,
  ProgressBarValueProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: ProgressBarValueProps = props;
  const intl = useIntl();

  const progressBarDefaultLabel = intl.formatMessage({
    defaultMessage: 'Loading',
    id: '3J6qHQEUwDxvZuIl',
    description: 'Default label for the progress-bar.',
  });

  const { variant, density } = _useSharedProgressBarPropsContext();

  const childIsText = _isStringChildren(children);

  return (
    <div
      data-testid={dataTestId}
      ref={forwardedRef}
      className={clsx(
        consumerClassName,
        progressBarValueCSS({ variant, size: density, childIsText }),
        textStyleCSS({ textStyle: 'small' }),
      )}
      style={consumerStyle}
      {...remainingProps}
    >
      {children || progressBarDefaultLabel}
    </div>
  );
});

(
  ProgressBarValue as typeof ProgressBarValue & { displayName: string }
).displayName = 'ProgressBar.Value';
